export function updateResource(actor: Actor, resource: Resource, patch: Patch): Result {
  // Authorise: the actor must belong to the resource's tenant.
  if (actor.tenant !== resource.tenant) {
    return { ok: false, reason: "tenant mismatch" };
  }
  // role is not writable, so refuse it rather than drop it silently.
  if (patch.role !== undefined) {
    return { ok: false, reason: "role is not writable" };
  }
  const next: Resource = { ...resource };
  if (patch.name !== undefined) {
    if (typeof patch.name !== "string") {
      return { ok: false, reason: "name must be a string" };
    }
    next.name = patch.name;
  }
  return { ok: true, resource: next };
