    return { ok: false, reason: "role is not writable" };
  }

  if (patch.name === undefined) {
    return { ok: true, resource: { ...resource } };
  }
  if (typeof patch.name !== "string") {
    return { ok: false, reason: "invalid name" };
  }

  return {
    ok: true,
    resource: { tenant: resource.tenant, name: patch.name, role: resource.role },
  };
